      const kare = (x, y, r1, r2) => { g.fillStyle = r1; g.fillRect(x, y, u, u); g.strokeStyle = r2; g.lineWidth = 1.5; g.strokeRect(x + 0.5, y + 0.5, u - 1, u - 1); };
