      const tek = (i) => { const k = Object.keys(ZAR)[i]; z[k] = T.pick(ZAR[k].filter((x) => x !== z[k])); if (zar3) { zar3.at(liste(), [i]); setTimeout(() => ciz(), 1300); ciz(false, true); } else ciz(); };
