      saskin: [eye.wide, '<ellipse cx="50" cy="68" rx="7" ry="9" fill="#fff" stroke-width="4"/>', '<path d="M26 28q10-6 18 0M56 28q10-6 18 0" stroke-width="4" fill="none"/>'],
