        const termo = h("div.dy-termo", h("div.dy-tlabel", "Ne kadar?"), h("div.dy-tbar", [1, 2, 3, 4, 5].map((n) => h("button", { "aria-pressed": String(n <= siddet), "aria-label": n + " / 5", onclick: () => { siddet = n; ciz(); } }, n))), h("div.dy-tends", h("span", "Biraz"), h("span", "Çok")));
