      const ciz = () => { ust.replaceChildren(h("div.seg", TAKIL.map(([id, ad]) => h("button", { "aria-pressed": String(id === sec), onclick: () => { sec = id; ciz(); } }, ad)))); ic.replaceChildren(); T.tools[sec] && T.tools[sec].render(ic, api); };
