/* ---- komut.js ---- */
/* Hızlı arama: Ctrl+K ya da üst çubuktaki büyüteç. Araç, etkinlik, bölüm ve komutları tek kutuda bulur. */
(function () {
  const h = T.h;
  const sade = (s) => (s || "").toLocaleLowerCase("tr-TR").replace(/[âà]/g, "a").replace(/[îı]/g, "i").replace(/[ûü]/g, "u").replace(/ö/g, "o").replace(/ç/g, "c").replace(/ş/g, "s").replace(/ğ/g, "g");
  function katalog() {
    const l = [];
    Object.entries(T.sections).forEach(([k, s]) => { if (s.title && !["ekran"].includes(k)) l.push({ ad: (T.dersAdi()[k]) || s.title, tur: "Bölüm", ic: s.icon, ac: () => T.go(k) }); });
    Object.entries(T.widgets || {}).forEach(([k, w]) => { if (w.title) l.push({ ad: w.title, tur: "Araç", ic: w.icon, ac: () => { const t = T.board.aktif() ? T.board : T.yuzen; t.add(k); } }); });
    Object.entries(T.tools).forEach(([k, t]) => {
      if (!t.title || t.gizli || /^k[zk]-/.test(k)) return; const sec = t.back || "matematik"; if (!T.sections[sec]) return;
      l.push({ ad: t.title, tur: (T.sections[sec].title || sec), ek: t.short || t.desc || "", ic: t.ikon3 || t.icon, ac: () => T.go(sec + "-" + k) });
    });
    const komut = (ad, ic, ac, ek) => l.push({ ad, tur: "Komut", ic, ac, ek });
    komut("Ekran perdesi", "moon", () => T.perde(), "Kısayol: B");
    komut("Arka planı değiştir", "bg", () => T.arkaPlanSec && T.arkaPlanSec());
    komut("Odaklanarak çalışma", "lotus", () => T.ambiyans && T.ambiyans.sec());
    komut("Sınıf değiştir", "class", () => T.pickClass());
    komut("Tam ekran", "full", () => (document.fullscreenElement ? document.exitFullscreen() : document.documentElement.requestFullscreen()).catch(() => {}));
    (T.ekKomutlar || []).forEach((x) => l.push(Object.assign({ tur: "Komut" }, x)));
    const gor = new Set(); return l.filter((x) => { const a = x.tur + "|" + x.ad; if (gor.has(a)) return false; gor.add(a); return true; });
  }
  function puan(x, q) {
    const a = sade(x.ad), e = sade(x.ek + " " + x.tur);
    if (a === q) return 100; if (a.startsWith(q)) return 80;
    if (a.split(/\s+/).some((w) => w.startsWith(q))) return 60;
    if (a.includes(q)) return 40;
    const p = q.split(/\s+/).filter(Boolean); if (p.length && p.every((w) => a.includes(w) || e.includes(w))) return 20;
    return 0;
  }
  T.komutPaleti = function () {
    if (T.$(".ara-perde")) return;
    const L = katalog();
    const giris = h("input.ara-giris", { placeholder: "Ne açalım? Örneğin zamanlayıcı, kesir, duygu", "aria-label": "Ara", autocomplete: "off" });
    const liste = h("div.ara-liste", { role: "listbox" });
    let sonuc = [], sec = 0;
    const kapat = () => { perde.remove(); removeEventListener("keydown", tus, true); };
    const calistir = (x) => { kapat(); try { x.ac(); } catch (e) { console.error(e); } };
    const ciz = () => {
      const q = sade(giris.value.trim());
      sonuc = q ? L.map((x) => [puan(x, q), x]).filter((y) => y[0] > 0).sort((a, b) => b[0] - a[0]).slice(0, 30).map((y) => y[1]) : L.filter((x) => x.tur === "Araç" || x.tur === "Komut").slice(0, 14);
      sec = Math.min(sec, Math.max(0, sonuc.length - 1));
      liste.replaceChildren(...(sonuc.length ? sonuc.map((x, i) => h("button.ara-oge", { role: "option", "aria-selected": String(i === sec), onclick: () => calistir(x), onpointermove: () => { if (sec !== i) { sec = i; isaretle(); } } }, T.icon3d(x.ic || "spark"), h("span", h("b", x.ad), x.ek ? h("small", x.ek) : null), h("em", x.tur))) : [h("p.ara-bos", "Bulunamadı. Başka bir sözcük dene.")]));
    };
    const isaretle = () => [...liste.children].forEach((b, i) => { b.setAttribute("aria-selected", String(i === sec)); if (i === sec) b.scrollIntoView({ block: "nearest" }); });
    const tus = (e) => {
      if (e.key === "Escape") { e.preventDefault(); kapat(); }
      else if (e.key === "ArrowDown") { e.preventDefault(); sec = Math.min(sec + 1, sonuc.length - 1); isaretle(); }
      else if (e.key === "ArrowUp") { e.preventDefault(); sec = Math.max(sec - 1, 0); isaretle(); }
      else if (e.key === "Enter" && sonuc[sec]) { e.preventDefault(); calistir(sonuc[sec]); }
    };
    giris.addEventListener("input", () => { sec = 0; ciz(); });
    const perde = h("div.ara-perde", { onclick: (e) => { if (e.target === perde) kapat(); } },
      h("div.ara-kutu", { role: "dialog", "aria-label": "Hızlı arama" }, h("div.ara-ust", T.icon("search"), giris, h("kbd", "Esc")), liste));
    document.body.append(perde); addEventListener("keydown", tus, true);
    ciz(); setTimeout(() => giris.focus(), 20);
  };
  addEventListener("keydown", (e) => {
    if ((e.ctrlKey || e.metaKey) && (e.key === "k" || e.key === "K")) { e.preventDefault(); T.komutPaleti(); }
    else if (e.key === "/" && !/INPUT|TEXTAREA|SELECT/.test(e.target.tagName || "") && !e.target.isContentEditable) { e.preventDefault(); T.komutPaleti(); }
  });
  /* üst çubuğa büyüteç */
  const ekle = () => { const r = T.$("#topbar .tb-right"); if (r && !r.querySelector(".tb-ara")) r.prepend(h("button.chip-btn.tb-ara", { onclick: () => T.komutPaleti(), "aria-label": "Ara (Ctrl+K)", title: "Ara (Ctrl+K)" }, T.icon("search"), h("span.lbl", "Ara"))); };
  new MutationObserver(ekle).observe(T.$("#topbar"), { childList: true }); ekle();
})();

/* Öğrenci kilidi: tahta öğrenciye bırakılınca menü, kapatma ve sayfa değiştirme kapanır.
   Açmak için sağ alttaki kilide 2 saniye basılı tutulur. */
(function () {
  const h = T.h; let kilitHash = null, dug = null;
  const kilitli = () => document.documentElement.classList.contains("kilitli");
  T.kilitliMi = kilitli;
  T.kilit = function () {
    if (kilitli()) return;
    kilitHash = location.hash || "#ana";
    document.documentElement.classList.add("kilitli");
    let zam = null; const halka = h("i.kl-halka");
    const birak = () => { clearTimeout(zam); dug.classList.remove("basili"); };
    dug = h("button#kilit-dug", { "aria-label": "Kilidi açmak için 2 saniye basılı tut", title: "Açmak için 2 saniye basılı tut",
      onpointerdown: (e) => { e.preventDefault(); dug.classList.add("basili"); zam = setTimeout(() => { birak(); T.kilitAc(); }, 2000); },
      onpointerup: birak, onpointerleave: birak, onpointercancel: birak, oncontextmenu: (e) => e.preventDefault() }, halka, T.icon("lock"), h("span", "Öğrenci modu"));
    document.body.append(dug);
    T.toast("Öğrenci modu açık. Açmak için kilide 2 saniye basılı tut");
  };
  T.kilitAc = function () { document.documentElement.classList.remove("kilitli"); if (dug) dug.remove(); dug = null; kilitHash = null; T.toast("Öğrenci modu kapandı"); };
  /* kilitliyken başka bölüme geçilmez; aynı bölümün etkinlikleri açılabilir */
  addEventListener("hashchange", () => { const bol = (x) => (x || "#ana").slice(1).split("-")[0]; if (kilitli() && kilitHash && bol(location.hash) !== bol(kilitHash)) history.replaceState(null, "", kilitHash) || T.route(); }, true);
  addEventListener("keydown", (e) => { if (kilitli() && ((e.ctrlKey || e.metaKey) || e.key === "/" || e.key === "b" || e.key === "B" || e.key === "Escape")) { e.stopImmediatePropagation(); if (e.ctrlKey || e.metaKey || e.key === "/") e.preventDefault(); } }, true);
  T.ekKomutlar = (T.ekKomutlar || []).concat({ ad: "Öğrenci modu (kilit)", ic: "lock", ac: () => T.kilit(), ek: "Menü ve kapatma düğmeleri gizlenir" });
})();

/* Okuma kolaylığı: okumakta zorlanan öğrenciler için harfleri ayırt etmesi kolay yazı tipi, geniş harf ve satır aralığı */
(function () {
  const anahtar = "ta-okuma-kolay";
  T.okumaKolay = () => { try { return localStorage.getItem(anahtar) === "1"; } catch (e) { return false; } };
  T.okumaKolayYap = (on) => { try { on ? localStorage.setItem(anahtar, "1") : localStorage.removeItem(anahtar); } catch (e) {} document.documentElement.classList.toggle("okuma-kolay", !!on); };
  document.documentElement.classList.toggle("okuma-kolay", T.okumaKolay());
  T.ekKomutlar = (T.ekKomutlar || []).concat({ ad: "Okuma kolaylığı aç veya kapat", ic: "book", ac: () => { const on = !T.okumaKolay(); T.okumaKolayYap(on); T.toast(on ? "Okuma kolaylığı açık" : "Okuma kolaylığı kapalı"); }, ek: "Geniş aralık, kolay ayırt edilen harfler" });
})();

/* Yazdırma yardımcısı: verilen öğeyi tek başına kâğıda basar. Yeni çıktılar bunu kullanır. */
T.yazdir = function (icerik, yon = "portrait") {
  const kap = T.h("div#ta-baski", icerik);
  const st = T.h("style#ta-baski-stil", "@page { size: A4 " + yon + "; margin: 12mm; }");
  document.head.append(st); document.body.append(kap); document.documentElement.classList.add("ta-yazdiriliyor");
  const bitir = () => { document.documentElement.classList.remove("ta-yazdiriliyor"); kap.remove(); st.remove(); removeEventListener("afterprint", bitir); };
  addEventListener("afterprint", bitir);
  setTimeout(() => { try { window.print(); } catch (e) {} setTimeout(bitir, 1500); }, 80);
};

/* İnternet kesilince de açılsın diye service worker kaydı */
if ("serviceWorker" in navigator && (location.protocol === "https:" || location.hostname === "localhost")) addEventListener("load", () => navigator.serviceWorker.register("/sw.js").catch(() => {}));

/* Tahta hafızası: Türkçe ve Matematik'te en son açılan etkinlik bölüm sayfasının başında "Kaldığın yer" olarak durur */
(function () {
  const BOL = ["turkce", "matematik"]; const A = "ta-son-arac";
  const oku = () => { try { return JSON.parse(localStorage.getItem(A) || "{}"); } catch (e) { return {}; } };
  addEventListener("hashchange", () => { const m = location.hash.slice(1).match(/^(turkce|matematik)-(.+)$/); if (!m || !T.tools[m[2]] || /^k[zk]-/.test(m[2])) return; const v = oku(); v[T.store.get().activeClassId + ":" + m[1]] = { id: m[2], t: Date.now() }; try { localStorage.setItem(A, JSON.stringify(v)); } catch (e) {} });
  const ekle = () => {
    const b = location.hash.slice(1); if (!BOL.includes(b)) return;
    const bas = document.querySelector("#view .page-head"); if (!bas || bas.querySelector(".kaldigin")) return;
    const k = oku()[T.store.get().activeClassId + ":" + b]; if (!k || !T.tools[k.id]) return;
    const gun = new Date(k.t), bugun = T.isoDate(gun) === T.isoDate();
    bas.append(T.h("button.kaldigin", { onclick: () => T.go(b + "-" + k.id), title: "En son açtığın etkinlik" }, T.icon("turn"), T.h("span", "Kaldığın yer: ", T.h("b", T.tools[k.id].title)), bugun ? null : T.h("small", gun.toLocaleDateString("tr-TR", { day: "numeric", month: "short" }))));
  };
  const v = document.getElementById("view"); if (v) new MutationObserver(ekle).observe(v, { childList: true, subtree: false });
})();

/* Etkinlik şeridinin sağ ucu: tam ekran, saat ve "Diğer" menüsü (ders ekranına kısayol burada) */
T.seritSonu = function (id) {
  const h = T.h;
  const saat = h("span.serit-saat"); const yaz = () => { if (!saat.isConnected && saat._b) return clearInterval(saat._iv); saat._b = true; const d = new Date(); saat.textContent = T.pad(d.getHours()) + ":" + T.pad(d.getMinutes()); };
  yaz(); saat._iv = setInterval(yaz, 15000);
  const diger = h("button.btn.icon.c-chalk", { "aria-label": "Diğer", title: "Diğer", onclick: (e) => {
    const eski = document.querySelector(".serit-menu"); if (eski) return eski.remove();
    const r = e.currentTarget.getBoundingClientRect();
    const m = h("div.serit-menu", { style: { top: r.bottom + 6 + "px", right: Math.max(8, innerWidth - r.right) + "px" } },
      h("button", { onclick: () => { m.remove(); T.board.add("toollink", { data: { tool: id }, w: 280, h: 170 }); T.toast("Ders ekranına eklendi"); } }, T.icon("board"), "Ders ekranına kısayol"),
      T.kisayolEkle ? h("button", { onclick: () => { m.remove(); T.kisayolEkle(id); } }, T.icon("pin"), "Ana sayfaya kısayol") : null,
      h("button", { onclick: () => { m.remove(); T.ogrenciBoyu && T.ogrenciBoyu(); } }, T.icon("hand"), "Öğrenci boyu"));
    document.body.append(m);
    const kapa = (ev) => { if (!m.contains(ev.target)) { m.remove(); document.removeEventListener("pointerdown", kapa, true); } }; setTimeout(() => document.addEventListener("pointerdown", kapa, true), 0);
  } }, "⋯");
  const tam = h("button.btn.icon.c-chalk", { "aria-label": "Tam ekran", title: "Tam ekran", onclick: () => { try { document.fullscreenElement ? document.exitFullscreen() : document.documentElement.requestFullscreen(); } catch (e) {} } }, T.icon("full"));
  return h("div.serit-son", diger, tam, saat);
};

/* Kartları düzenle: raptiye ve gizleme düğmeleri yalnızca bu mod açıkken (ya da fareyle üzerine gelince) görünür */
(function () {
  const ekle = () => {
    const bas = document.querySelector("#view .page-head"); if (!bas || bas.querySelector(".kart-duzenle-dug") || !document.querySelector("#view .tc-pin, #view .tc-gizle")) return;
    const on = () => document.documentElement.classList.contains("kart-duzenle");
    const b = T.h("button.kart-duzenle-dug", { "aria-pressed": String(on()), onclick: () => { document.documentElement.classList.toggle("kart-duzenle"); b.setAttribute("aria-pressed", String(on())); b.lastChild.textContent = on() ? "Bitti" : "Kartları düzenle"; } }, T.icon("edit"), T.h("span", on() ? "Bitti" : "Kartları düzenle"));
    bas.append(b);
  };
  const v = document.getElementById("view"); if (v) new MutationObserver(() => setTimeout(ekle, 0)).observe(v, { childList: true });
  addEventListener("hashchange", () => document.documentElement.classList.remove("kart-duzenle"));
})();

/* ---- tasi.js ---- */
/* Evden tahtaya taşı: üyelik olmadan hazırlığı sıkıştırılmış bir bağlantıya ya da QR koda koyar.
   Bağlantı sunucuya gitmez; her şey adresin # kısmında durur. Tahtada açılınca hazırlık içe alınır. */
(function () {
  const { h } = T;
  const b64 = (u8) => { let s = ""; u8.forEach((c) => (s += String.fromCharCode(c))); return btoa(s).replace(/\+/g, "-").replace(/\//g, "_").replace(/=+$/, ""); };
  const unb64 = (s) => { s = s.replace(/-/g, "+").replace(/_/g, "/"); while (s.length % 4) s += "="; return Uint8Array.from(atob(s), (c) => c.charCodeAt(0)); };
  const akis = async (veri, tur) => { const st = new Blob([veri]).stream().pipeThrough(tur); return new Uint8Array(await new Response(st).arrayBuffer()); };
  const paketle = async (o) => { const ham = new TextEncoder().encode(JSON.stringify(o)); return window.CompressionStream ? "z" + b64(await akis(ham, new CompressionStream("deflate-raw"))) : b64(ham); };
  const coz = async (s) => { const sik = s[0] === "z"; const u8 = unb64(sik ? s.slice(1) : s); const ham = sik && window.DecompressionStream ? await akis(u8, new DecompressionStream("deflate-raw")) : u8; return JSON.parse(new TextDecoder().decode(ham)); };
  T.tasiPaketle = paketle; T.tasiCoz = coz;

  T.tasiPenceresi = function () {
    const s = T.store.get(), cid = s.activeClassId, k = s.kokpit || {};
    const planlar = (s.plans || []).slice(0, 12);
    const sec = new Set(planlar.slice(0, 1).map((p) => p.id));
    const not = h("textarea.in", { rows: 3, placeholder: "Sabah tahtada görmek istediğin not ya da yönerge" }); not.value = ((k.not || {})[cid] || "").slice(0, 600);
    const soru = h("input.in", { placeholder: "Günün sorusu (isteğe bağlı)", value: (k.ozelKivilcim || {})[cid] || "" });
    const bilet = h("input.in", { placeholder: "Çıkış bileti sorusu (isteğe bağlı)" });
    const sonuc = h("div.ts-sonuc");
    const govde = h("div.ts",
      h("p.hint", { style: { margin: 0 } }, "Evde hazırladığını sabah tahtaya taşı. Hesap gerekmez: bilgiler bağlantının içinde durur, sunucuya gönderilmez. Öğrenci adları bağlantıya eklenmez."),
      planlar.length ? h("div", h("b", "Planlar"), h("div.ts-planlar", planlar.map((p) => h("label.ts-plan", h("input", { type: "checkbox", checked: sec.has(p.id) ? true : null, onchange: (e) => (e.target.checked ? sec.add(p.id) : sec.delete(p.id)) }), h("span", p.baslik || p.title || "Plan", h("small", (p.ders || "") + (p.at ? " · " + new Date(p.at).toLocaleDateString("tr-TR") : "")))))))
        : h("p.hint", "Kaydedilmiş planın yok. Plan bölümünde hazırlayıp kaydedebilirsin."),
      h("b", "Not"), not, h("b", "Günün sorusu"), soru, h("b", "Çıkış bileti"), bilet, sonuc);
    const uret = async () => {
      const o = { v: 1, plan: (s.plans || []).filter((p) => sec.has(p.id)).map((p) => { const c = Object.assign({}, p); delete c.id; return c; }), not: not.value.trim(), soru: soru.value.trim(), bilet: bilet.value.trim() };
      if (!o.plan.length && !o.not && !o.soru && !o.bilet) { T.toast("Taşınacak bir şey seç ya da yaz"); return; }
      const p = await paketle(o), url = location.origin + location.pathname + "#tasi=" + p;
      const qr = h("div.ts-qr");
      sonuc.replaceChildren(h("b", "Bağlantın hazır"), h("div.row", { style: { gap: "6px" } }, h("input.in", { value: url, readonly: true, onclick: (e) => e.target.select(), style: { flex: 1 } }),
        h("button.btn.sm.c-sky", { onclick: () => { navigator.clipboard && navigator.clipboard.writeText(url).then(() => T.toast("Bağlantı kopyalandı"), () => T.toast("Kopyalanamadı, elle seç")); } }, "Kopyala")),
        h("p.hint", { style: { margin: 0 } }, "Kendine e-postayla gönder ya da tahtanın kamerasıyla QR kodu okut. " + (url.length > 2300 ? "Bağlantı QR için uzun; kopyalayıp gönder." : "")), qr);
      if (url.length <= 2300 && window.QRCode) { try { new window.QRCode(qr, { text: url, width: 240, height: 240, correctLevel: window.QRCode.CorrectLevel.L }); } catch (e) {} }
    };
    T.modal({ title: "Evden tahtaya taşı", wide: true, body: govde, actions: [{ label: "Bağlantı oluştur", tone: "c-leaf", onClick: () => { uret(); return false; } }, { label: "Kapat" }] });
  };

  /* Tahtada açılış: #tasi= ile gelindiyse önce sor, sonra içe al */
  async function gelen(p) {
    let o; try { o = await coz(p); } catch (e) { T.toast("Bağlantı okunamadı"); return; }
    const parca = [o.plan && o.plan.length ? o.plan.length + " plan" : null, o.not ? "not" : null, o.soru ? "günün sorusu" : null, o.bilet ? "çıkış bileti" : null].filter(Boolean);
    T.modal({ title: "Evden gelen hazırlık", body: h("div", { style: { display: "grid", gap: "8px" } }, h("p", { style: { margin: 0 } }, "Bu bağlantıda " + parca.join(", ") + " var. " + T.store.activeClass().name + " sınıfına alınsın mı?"),
        o.not ? h("p.hint", { style: { margin: 0, whiteSpace: "pre-wrap" } }, "Not: " + o.not.slice(0, 200)) : null),
      actions: [{ label: "Vazgeç" }, { label: "İçe al", tone: "c-leaf", onClick: () => {
        T.store.update((s) => {
          const cid = s.activeClassId; s.kokpit = s.kokpit || {};
          (o.plan || []).forEach((p) => s.plans.unshift(Object.assign({}, p, { id: T.uid(), at: Date.now() })));
          if (o.not) { s.kokpit.not = s.kokpit.not || {}; s.kokpit.not[cid] = o.not; }
          if (o.soru) { s.kokpit.ozelKivilcim = s.kokpit.ozelKivilcim || {}; s.kokpit.ozelKivilcim[cid] = o.soru; s.kokpit.kivilcimI = -1; }
          if (o.bilet) s.tasiBilet = o.bilet;
        });
        T.toast("Hazırlık içe alındı"); T.go(o.plan && o.plan.length ? "plan" : "ana");
        if (o.bilet) setTimeout(() => { const t = T.board && T.board.aktif && T.board.aktif() ? T.board : T.yuzen; t && t.add("ticket", { data: { q: o.bilet, c: [0, 0, 0] } }); }, 600);
      } }] });
  }
  if (location.hash.startsWith("#tasi=")) { const p = location.hash.slice(6); history.replaceState(null, "", location.pathname + "#ana"); addEventListener("load", () => setTimeout(() => gelen(p), 900)); }
  addEventListener("hashchange", () => { if (location.hash.startsWith("#tasi=")) { const p = location.hash.slice(6); history.replaceState(null, "", location.pathname + "#ana"); T.route && T.route(); gelen(p); } });
  /* Zümre içi paylaşım: ölçek, plan, soru listesi ya da sahne bir bağlantıya dönüşür; açan öğretmen kendi sitesine alır */
  const TURAD = { olcek: "Ölçek", plan: "Plan", sorular: "Soru listesi", sahne: "Ekran sahnesi" };
  T.sablonPaylas = async function (tur, nesne, ad) {
    const p = await paketle({ v: 1, sablon: tur, ad: ad || "", veri: nesne }), url = location.origin + location.pathname + "#al=" + p;
    const qr = h("div.ts-qr");
    T.modal({ title: TURAD[tur] + " paylaş", body: h("div.ts", h("p.hint", { style: { margin: 0 } }, "Bu bağlantıyı açan öğretmen " + (ad ? "\"" + ad + "\" " : "") + TURAD[tur].toLocaleLowerCase("tr") + " şablonunu kendi sitesine alır. Öğrenci adı ve puanlar bağlantıda yer almaz."),
      h("div.row", { style: { gap: "6px" } }, h("input.in", { value: url, readonly: true, onclick: (e) => e.target.select(), style: { flex: 1 } }), h("button.btn.sm.c-sky", { onclick: () => navigator.clipboard && navigator.clipboard.writeText(url).then(() => T.toast("Bağlantı kopyalandı")) }, "Kopyala")),
      h("button.btn.sm.c-chalk", { style: { justifySelf: "start" }, onclick: () => { const a = document.createElement("a"); a.href = URL.createObjectURL(new Blob([JSON.stringify({ sablon: tur, ad, veri: nesne }, null, 1)], { type: "application/json" })); a.download = (ad || tur).replace(/[^\wçğıöşüÇĞİÖŞÜ -]/g, "").slice(0, 40) + ".tahta.json"; a.click(); } }, T.icon("download"), "Dosya olarak indir"), qr), actions: [{ label: "Kapat" }] });
    if (url.length <= 2300 && window.QRCode) { try { new window.QRCode(qr, { text: url, width: 220, height: 220, correctLevel: window.QRCode.CorrectLevel.L }); } catch (e) {} }
  };
  function sablonAl(o) {
    const v = o.veri || {};
    T.modal({ title: "Paylaşılan " + (TURAD[o.sablon] || "şablon").toLocaleLowerCase("tr"), body: h("p", { style: { margin: 0 } }, (o.ad ? "\"" + o.ad + "\" " : "") + "sitene eklensin mi?"),
      actions: [{ label: "Vazgeç" }, { label: "Ekle", tone: "c-leaf", onClick: () => {
        T.store.update((s) => {
          const cid = s.activeClassId;
          if (o.sablon === "plan") s.plans.unshift(Object.assign({}, v, { id: T.uid(), at: Date.now() }));
          else if (o.sablon === "olcek") { s.olcmeArac = s.olcmeArac || {}; const c = (s.olcmeArac[cid] = s.olcmeArac[cid] || { olcekler: [] }); c.olcekler = c.olcekler || []; c.olcekler.unshift({ id: "o" + Date.now().toString(36), tur: v.tur || "olcek", ad: v.ad || "Paylaşılan ölçek", ders: v.ders || "", kriter: (v.kriter || []).slice(0, 20), puan: {}, tarih: T.isoDate() }); }
          else if (o.sablon === "sorular") { s.kokpit = s.kokpit || {}; s.kokpit.ozelKivilcim = s.kokpit.ozelKivilcim || {}; s.kokpit.ozelKivilcim[cid] = (v.sorular || [])[0] || ""; s.kokpit.kivilcimI = -1; }
        });
        if (o.sablon === "sahne") { try { const l = JSON.parse(localStorage.getItem("ta-sahneler") || "[]"); l.unshift({ ad: o.ad || "Paylaşılan sahne", bg: v.bg, list: v.list || [] }); localStorage.setItem("ta-sahneler", JSON.stringify(l.slice(0, 24))); } catch (e) {} }
        T.toast("Eklendi"); T.go(o.sablon === "plan" ? "plan" : o.sablon === "olcek" ? "olcme" : o.sablon === "sahne" ? "ekran" : "ana");
      } }] });
  }
  const alKontrol = async () => { if (!location.hash.startsWith("#al=")) return; const p = location.hash.slice(4); history.replaceState(null, "", location.pathname + "#ana"); try { sablonAl(await coz(p)); } catch (e) { T.toast("Paylaşım bağlantısı okunamadı"); } };
  if (location.hash.startsWith("#al=")) addEventListener("load", () => setTimeout(alKontrol, 900));
  addEventListener("hashchange", alKontrol);
  T.sablonDosyaAl = (f) => f.text().then((t) => sablonAl(JSON.parse(t))).catch(() => T.toast("Dosya okunamadı"));

  T.ekKomutlar = (T.ekKomutlar || []).concat({ ad: "Paylaşılan şablon dosyasını aç", ic: "download", ac: () => { const i = h("input", { type: "file", accept: ".json,application/json", onchange: (e) => e.target.files[0] && T.sablonDosyaAl(e.target.files[0]) }); i.click(); }, ek: ".tahta.json" }, { ad: "Evden tahtaya taşı", ic: "qr", ac: () => T.tasiPenceresi(), ek: "Plan, not ve soruyu bağlantıyla taşı" });
})();

/* ---- ekran-sahne.js ---- */
/* Ders ekranı sahneleri: sık kullanılan araç düzenleri tek dokunuşla kurulur, öğretmen kendi düzenini de saklar.
   Yan yana ekran: iki aracı üst üste binmeden 50/50 ya da 70/30 böler. Öğrenci boyu: ekranı aşağı indirir. */
(function () {
  const { h } = T;
  const A = "ta-sahneler";
  const kayitli = () => { try { return JSON.parse(localStorage.getItem(A) || "[]"); } catch (e) { return []; } };
  const kaydet = (l) => { try { localStorage.setItem(A, JSON.stringify(l)); } catch (e) { T.toast("Kaydedilemedi"); } };
  const HAZIR = [
    ["Grup çalışması", "groups", [{ type: "groups", x: 0, y: 0, w: 0.55, h: 1 }, { type: "timer", x: 0.55, y: 0, w: 0.45, h: 0.55 }, { type: "noise", x: 0.55, y: 0.55, w: 0.45, h: 0.45 }]],
    ["Sessiz okuma", "book", [{ type: "dogazaman", x: 0, y: 0, w: 0.6, h: 1, data: { sahne: "cicek", total: 900, left: 900 } }, { type: "text", x: 0.6, y: 0, w: 0.4, h: 0.55, data: { text: "Sessiz okuma zamanı\nKitabını seç, yerine otur, okumaya başla." } }, { type: "orman", x: 0.6, y: 0.55, w: 0.4, h: 0.45 }]],
    ["İstasyonlar", "groups", [{ type: "istasyon", x: 0, y: 0, w: 0.72, h: 1 }, { type: "noise", x: 0.72, y: 0, w: 0.28, h: 0.55 }, { type: "traffic", x: 0.72, y: 0.55, w: 0.28, h: 0.45 }]],
    ["Sınıf tartışması", "talk", [{ type: "sozagi", x: 0, y: 0, w: 0.6, h: 1 }, { type: "name", x: 0.6, y: 0, w: 0.4, h: 0.6 }, { type: "timer", x: 0.6, y: 0.6, w: 0.4, h: 0.4 }]],
    ["Bireysel çalışma", "pen", [{ type: "text", x: 0, y: 0, w: 0.5, h: 0.6, data: { text: "Bugünkü görevimiz\n1. \n2. \n3. " } }, { type: "timer", x: 0.5, y: 0, w: 0.5, h: 0.6 }, { type: "traffic", x: 0, y: 0.6, w: 0.5, h: 0.4 }, { type: "noise", x: 0.5, y: 0.6, w: 0.5, h: 0.4 }]],
  ];
  T.sahnePenceresi = function () {
    const govde = h("div.sh");
    const ciz = () => {
      const l = kayitli();
      govde.replaceChildren(
        h("b", "Hazır sahneler"), h("div.sh-izgara", HAZIR.map(([ad, ic, list]) => h("button.sh-kart", { onclick: () => { m.close(); T.board.sahneKur(list); } }, T.icon3d(ic), h("span", ad), h("small", list.map((x) => (T.widgets[x.type] || {}).title).filter(Boolean).join(", "))))),
        h("b", "Benim sahnelerim"),
        l.length ? h("div.sh-izgara", l.map((x, i) => h("div.sh-kart.kendi", h("button.sh-ac", { onclick: () => { m.close(); T.board.sahneKur(x.list, x.bg); } }, T.icon3d("star"), h("span", x.ad), h("small", x.list.length + " araç")),
          h("button.sh-sil.pay", { "aria-label": x.ad + " sahnesini paylaş", title: "Paylaş", onclick: () => T.sablonPaylas && T.sablonPaylas("sahne", { bg: x.bg, list: x.list }, x.ad) }, "↗"),
          h("button.sh-sil", { "aria-label": x.ad + " sahnesini sil", onclick: async () => { if (await T.confirm("Sahneyi sil", x.ad + " silinsin mi?", "Sil")) { const y = kayitli(); y.splice(i, 1); kaydet(y); ciz(); } } }, "×")))) : h("p.hint", { style: { margin: 0 } }, "Ders ekranında araçları istediğin gibi yerleştir, sonra aşağıdan sakla."),
        h("div.row", { style: { gap: "8px" } }, (() => { const inp = h("input.in", { placeholder: "Şu anki düzenin adı, ör. Kesir dersi", maxlength: 40 }); return [inp, h("button.btn.c-leaf", { onclick: () => { const v = T.board.sahneAl(); if (!v.list.length) return T.toast("Ders ekranında araç yok"); const y = kayitli(); y.unshift({ ad: inp.value.trim() || "Sahnem " + (y.length + 1), bg: v.bg, list: v.list }); kaydet(y.slice(0, 24)); T.toast("Sahne saklandı"); ciz(); } }, T.icon("save"), "Şu anki düzeni sakla")]; })()),
        h("b", "Yan yana ekran"), h("p.hint", { style: { margin: 0 } }, "İki aracı üst üste binmeden yan yana kur."), yanYana());
    };
    const m = T.modal({ title: "Sahneler", wide: true, body: govde, actions: [{ label: "Kapat" }] });
    ciz();
  };
  /* Yan yana: soldaki ve sağdaki aracı seç, oranı seç */
  function yanYana() {
    const secenek = Object.entries(T.widgets).filter(([, w]) => w.title).sort((a, b) => a[1].title.localeCompare(b[1].title, "tr"));
    const sol = h("select.in", { "aria-label": "Sol araç" }, secenek.map(([k, w]) => h("option", { value: k, selected: k === "text" ? true : null }, w.title)));
    const sag = h("select.in", { "aria-label": "Sağ araç" }, secenek.map(([k, w]) => h("option", { value: k, selected: k === "draw" ? true : null }, w.title)));
    let oran = 0.5;
    const seg = h("div.seg", [[0.5, "50 / 50"], [0.7, "70 / 30"], [0.3, "30 / 70"]].map(([v, l]) => h("button", { "aria-pressed": String(v === oran), onclick: (e) => { oran = v; [...seg.children].forEach((b) => b.setAttribute("aria-pressed", String(b === e.currentTarget))); } }, l)));
    return h("div.sh-yan", sol, sag, seg, h("button.btn.c-sky", { onclick: () => { T.$$(".modal-wrap, #layer > .scrim").forEach((x) => x.remove()); T.board.sahneKur([{ type: sol.value, x: 0, y: 0, w: oran, h: 1 }, { type: sag.value, x: oran, y: 0, w: 1 - oran, h: 1 }]); } }, "Yan yana kur"));
  }
  T.ekKomutlar = (T.ekKomutlar || []).concat({ ad: "Ders ekranı sahneleri", ic: "plan", ac: () => { T.go("ekran"); setTimeout(T.sahnePenceresi, 300); }, ek: "Grup çalışması, sessiz okuma, yan yana ekran" });

  /* Öğrenci boyu: küçük öğrenciler üst köşelere uzanamaz; sayfa ekranın alt bölümüne iner */
  T.ogrenciBoyu = function (on) {
    const html = document.documentElement; on = on == null ? !html.classList.contains("ogrenci-boyu") : on;
    html.classList.toggle("ogrenci-boyu", on);
    let d = document.getElementById("boy-dug");
    if (on && !d) document.body.append(h("button#boy-dug", { onclick: () => T.ogrenciBoyu(false), title: "Normal boya dön" }, "⬆ Normal boy"));
    if (!on && d) d.remove();
  };
  T.ekKomutlar.push({ ad: "Öğrenci boyu", ic: "hand", ac: () => T.ogrenciBoyu(), ek: "Ekranı aşağı indir, küçükler uzansın" });
})();

/* ---- kumanda.js ---- */
/* Cep kumandası ve defter kamerası: öğretmen tahtadaki QR'ı telefonuyla okutur (uygulama yok, giriş yok).
   Telefon sınıfın arkasından isim çeker, zamanlayıcıyı ve perdeyi yönetir, defter fotoğrafını tahtaya yansıtır.
   Bağlantı kısa ömürlüdür; fotoğraflar sunucuda saklanmaz. */
(function () {
  const { h } = T;
  let ws = null, oda = null, dur = false, gosterge = null, bagli = 0, deneme = 0;
  const yeniOda = () => { const a = new Uint8Array(16); crypto.getRandomValues(a); let s = ""; a.forEach((c) => (s += String.fromCharCode(c))); return btoa(s).replace(/\+/g, "-").replace(/\//g, "_").replace(/=+$/, ""); };
  const tahta = () => (T.board.aktif() ? T.board : T.yuzen);
  const widgetEl = (tip) => document.querySelector(`[data-w][data-type="${tip}"]`);
  const dugmeBas = (tip, metinler) => {
    let el = widgetEl(tip);
    const bas = () => { el = widgetEl(tip); if (!el) return; const b = [...el.querySelectorAll("button")].find((x) => metinler.some((m) => x.textContent.trim().startsWith(m))); b && b.click(); };
    if (!el) { tahta().add(tip); setTimeout(bas, 700); } else bas();
  };
  function fotoGoster(d) {
    fotoKapat();
    const img = h("img", { src: d, alt: "Defter fotoğrafı" });
    const cer = h("div.kf-cer", img);
    const katman = T.kalemKatmani ? T.kalemKatmani(cer) : cer;
    document.body.append(h("div#kumanda-foto", h("div.kf-ust", h("b", "📷 Defterden"), h("button.btn.c-chalk", { onclick: fotoKapat }, T.icon("close"), "Kapat")), katman));
  }
  const fotoKapat = () => { const e = document.getElementById("kumanda-foto"); if (e) e.remove(); };
  function komut(k) {
    if (k === "isim") dugmeBas("name", ["Çevir", "Çek"]);
    else if (k === "zaman") dugmeBas("timer", ["Başlat", "Durdur", "Devam"]);
    else if (k === "perde") T.perde && T.perde();
    else if (k === "sus") T.sssUyari && T.sssUyari(true);
    else if (k === "geri" || k === "ileri") dispatchEvent(new KeyboardEvent("keydown", { key: k === "geri" ? "ArrowLeft" : "ArrowRight", bubbles: true }));
    else if (k === "fotokapat") fotoKapat();
  }
  function gostergeCiz() {
    if (!oda || dur) { gosterge && gosterge.remove(); gosterge = null; return; }
    if (!gosterge) { gosterge = h("div#kumanda-gosterge"); document.body.append(gosterge); }
    gosterge.replaceChildren(h("span", bagli ? "📱 Kumanda bağlı" : "📱 Telefon bekleniyor"), h("button", { onclick: () => T.kumanda(), title: "QR kodu göster" }, "QR"), h("button", { onclick: kapat, title: "Kumandayı kapat" }, "×"));
  }
  function baglan() {
    const p = location.protocol === "https:" ? "wss:" : "ws:";
    try { ws = new WebSocket(p + "//" + location.host + "/api/kumanda?oda=" + oda + "&rol=tahta"); } catch (e) { T.toast("Kumanda bağlantısı kurulamadı"); return; }
    ws.onopen = () => { deneme = 0; gostergeCiz(); };
    ws.onmessage = (e) => { let m; try { m = JSON.parse(e.data); } catch (er) { return; }
      if (m.t === "baglandi") { bagli = m.n; T.toast("Telefon bağlandı"); const md = document.querySelector(".km-durum"); if (md) md.textContent = "Telefon bağlandı. Bu pencereyi kapatabilirsin."; }
      else if (m.t === "ayrildi") bagli = m.n;
      else if (m.t === "komut") komut(m.k);
      else if (m.t === "foto" && typeof m.d === "string" && m.d.startsWith("data:image/")) fotoGoster(m.d);
      gostergeCiz(); };
    ws.onclose = (e) => { ws = null; if (dur || e.code === 4000) return; if (deneme++ < 6) setTimeout(() => !dur && oda && baglan(), 2000 * deneme); else { T.toast("Kumanda bağlantısı koptu"); kapat(); } };
  }
  function kapat() { dur = true; try { ws && ws.close(); } catch (e) {} ws = null; oda = null; bagli = 0; gostergeCiz(); }
  T.kumanda = function () {
    if (!oda) { dur = false; oda = yeniOda(); baglan(); }
    const url = location.origin + "/kumanda.html#" + oda;
    const qr = h("div.km-qr");
    T.modal({ title: "Cep kumandası", body: h("div.km", h("p", { style: { margin: 0 } }, "Telefonunun kamerasıyla bu kodu okut. Uygulama ya da giriş gerekmez."), qr,
      h("p.km-durum", bagli ? "Telefon bağlı." : "Telefon bekleniyor…"),
      h("p.hint", { style: { margin: 0 } }, "Telefondan isim çekebilir, zamanlayıcıyı ve ekran perdesini yönetebilir, defterdeki bir çözümü fotoğraflayıp tahtaya yansıtabilirsin. Fotoğraflar hiçbir yerde saklanmaz; bağlantı en çok 3 saat sürer.")),
      actions: [{ label: "Kumandayı kapat", onClick: () => kapat() }, { label: "Tamam", tone: "c-leaf" }] });
    if (window.QRCode) { try { new window.QRCode(qr, { text: url, width: 240, height: 240, correctLevel: window.QRCode.CorrectLevel.M }); } catch (e) { qr.textContent = url; } } else qr.append(h("input.in", { value: url, readonly: true }));
    gostergeCiz();
  };
  T.ekKomutlar = (T.ekKomutlar || []).concat({ ad: "Cep kumandası ve defter kamerası", ic: "qr", ac: () => T.kumanda(), ek: "Telefondan isim çek, fotoğraf yansıt" });
})();
